            }
            {
                uint offsetValue = (uint)(value.RotationW) - unchecked((uint)(-1024));
                if (!batch.SerializeBits(ref offsetValue, 12))
                {
                    return false;
                }
            }
            if (!batch.SerializeBits64(ref value.Flags, 64))
            {
                return false;
            }
            return true;
        }

        public static bool ReadTurretData_Shallow(ReadStream stream, TurretData_Shallow value)
        {
            ReadBatch batch = stream.BeginBatch();
            bool result = ReadTurretData_ShallowBatch(ref batch, value);
            batch.End(); // on every path out — End publishes the cursor and the error
            return result;
        }

        // The batch-form core — INLINE-ONLY: a non-inlined call taking the batch by
        // ref address-exposes it and enregistration dies (measured 0.71x, worse than
        // no batch). Nested types compose core-to-core by ref, never via the stream.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool ReadTurretData_ShallowBatch(ref ReadBatch batch, TurretData_Shallow value)
        {
            if (!ReadHandleBatch(ref batch, value.Parent))
            {
                return false;
            }
            if (!batch.SerializeInt(ref value.TurretIndex, 0, (int)(MaxTurretsPerShip - 1)))
            {
                return false;
            }
            {
                int componentValue = 0;
                if (!batch.SerializeInt(ref componentValue, -1024, 1024))
                {
                    return false;
                }
                value.RotationX = (short)componentValue;
            }
            {
                int componentValue = 0;
                if (!batch.SerializeInt(ref componentValue, -1024, 1024))
                {
                    return false;
                }
                value.RotationY = (short)componentValue;
            }
            {
                int componentValue = 0;
                if (!batch.SerializeInt(ref componentValue, -1024, 1024))
                {
                    return false;
                }
                value.RotationZ = (short)componentValue;
            }
            {
                int componentValue = 0;
                if (!batch.SerializeInt(ref componentValue, -1024, 1024))
                {
                    return false;
                }
                value.RotationW = (short)componentValue;
            }
            if (!batch.SerializeBits64(ref value.Flags, 64))
            {
                return false;
            }
            return true;
        }

        public static void QuantizeTurret(TurretData_Interpolate input, TurretData_Shallow output)
        {
            output.Parent.ObjectId = input.Parent.ObjectId;
            output.Parent.ObjectSequence = input.Parent.ObjectSequence;
            output.TurretIndex = input.TurretIndex;
            {
                double quantizedValue = Math.Floor(input.Rotation.X * (double)RotationUnits + 0.5);
                long componentValue = -1024;
                if (quantizedValue > 1024.0)
                {
                    componentValue = 1024;
                }
                else if (quantizedValue >= -1024.0)
                {
                    componentValue = (long)quantizedValue;
                }
                output.RotationX = (short)componentValue;
            }
            {
                double quantizedValue = Math.Floor(input.Rotation.Y * (double)RotationUnits + 0.5);
                long componentValue = -1024;
                if (quantizedValue > 1024.0)
                {
                    componentValue = 1024;
                }
                else if (quantizedValue >= -1024.0)
                {
                    componentValue = (long)quantizedValue;
                }
                output.RotationY = (short)componentValue;
            }
            {
                double quantizedValue = Math.Floor(input.Rotation.Z * (double)RotationUnits + 0.5);
                long componentValue = -1024;
                if (quantizedValue > 1024.0)
                {
                    componentValue = 1024;
                }
                else if (quantizedValue >= -1024.0)
                {
                    componentValue = (long)quantizedValue;
                }
                output.RotationZ = (short)componentValue;
            }
            {
                double quantizedValue = Math.Floor(input.Rotation.W * (double)RotationUnits + 0.5);
                long componentValue = -1024;
                if (quantizedValue > 1024.0)
                {
                    componentValue = 1024;
                }
                else if (quantizedValue >= -1024.0)
                {
                    componentValue = (long)quantizedValue;
                }
                output.RotationW = (short)componentValue;
            }
            output.Flags = input.Flags;
        }

        public static void UnquantizeTurret(TurretData_Shallow input, TurretData_Interpolate output)
        {
            output.Parent.ObjectId = input.Parent.ObjectId;
            output.Parent.ObjectSequence = input.Parent.ObjectSequence;
            output.TurretIndex = input.TurretIndex;
            output.Rotation.X = (double)input.RotationX / (double)RotationUnits;
            output.Rotation.Y = (double)input.RotationY / (double)RotationUnits;
            output.Rotation.Z = (double)input.RotationZ / (double)RotationUnits;
            output.Rotation.W = (double)input.RotationW / (double)RotationUnits;
            output.Flags = input.Flags;
        }

        // The object tag wire: ObjectType in [0, 4], minimal bits; None = 0 is the
        // null — the sentinel the surveyed baseline streams terminate with (SPEC §4.8).
        // The write folds the tag's bit count at generation time (byte-identical to
        // the ranged form); a tag outside the set is refused — bool alone.
        public static bool WriteObjectType(WriteStream stream, ObjectType value)
        {
            uint tagValue = (uint)value;
            if (tagValue > 4)
            {
                return false;
            }
            return stream.SerializeBits(ref tagValue, 3);
        }

        public static bool ReadObjectType(ReadStream stream, ref ObjectType value)
        {
            int tagValue = 0;
            if (!stream.SerializeInt(ref tagValue, 0, 4))
            {
                return false;
            }
            value = (ObjectType)tagValue;
            return true;
        }
    }

}
